const input = $input.first().json;
const company = {
  id: "263e2d0f-8370-4f72-a9f8-01c6fcc9d2a5",
  name: "Barbearia Exemplo",
  slug: "barbearia-exemplo"
};

const event = {
  event: "ticketz.message.received",
  company,
  receivedAt: new Date().toISOString(),
  ticket: input.ticket,
  customer: input.customer,
  message: input.message,
  raw: input
};

let vib = { sent: false };
try {
  vib = await this.helpers.httpRequest({
    method: "POST",
    url: "http://11.88.88.8:3101/api/n8n/events",
    headers: {
      "Content-Type": "application/json"
    },
    body: event,
    json: true
  });
} catch (error) {
  vib = { sent: false, error: error.message };
}

return [{ json: { ok: true, company, vib, event } }];
